  }

  sycl::queue q{sycl::default_selector_v};
  float *d_inp = sycl::malloc_device<float>(n == 0 ? 1 : n, q);
  float *d_out = sycl::malloc_device<float>(n == 0 ? 1 : n, q);
  if (!d_inp || !d_out) {
